update public.aml_fintech_entity
set website='https://home.embedx.io/',refreshed_at=now()
where fintech_id='ENT-RUT-77277142-8';

with vals(fintech_id,business_model,target_customer,revenue_model,bm_conf,tc_conf,rev_conf,bm_basis,tc_basis,rev_basis,source_url) as (
 values
 ('ENT-RUT-76052998-2','B2B2C','AMBOS',null,0.999::numeric,0.999::numeric,null,'ComparaOnline opera un marketplace digital de seguros y productos financieros para consumidores y, mediante su corredora relacionada, intermedia seguros con compañías aseguradoras.','La plataforma atiende usuarios finales que comparan/contratan y mantiene relaciones B2B con aseguradoras/proveedores financieros.','El sitio explica que la corredora intermedia pólizas y que la sociedad titular compara/redirige productos, pero no expone una estructura de remuneración suficientemente homogénea para asignar un único código.','https://www.comparaonline.cl/'),
 ('ENT-RUT-77277142-8','B2B','EMPRESAS','SUSCRIPCION_SAAS',0.999::numeric,0.999::numeric,0.99::numeric,'EmbedX provee un core modular y soluciones de embedded insurance que aseguradoras y empresas integran para venta, postventa, siniestros y canales affinity.','Los clientes observados son aseguradoras, corredores y empresas que incorporan seguros a sus canales digitales.','La solución se comercializa como plataforma tecnológica B2B modular; se mantiene la monetización SaaS ya estructurada.','https://home.embedx.io/'),
 ('ENT-RUT-76894372-9','B2B2C','AMBOS',null,0.999::numeric,0.999::numeric,null,'Gerty combina marketplace de salud para pacientes con infraestructura para clínicas, aseguradoras y empresas que gestiona beneficios, siniestros y pagos de salud.','La oferta vigente atiende pacientes/personas y organizaciones: clínicas, aseguradoras y empresas.','La evidencia pública revisada describe la red y servicios, pero no publica una estructura de precios suficientemente representativa para asignar un único modelo de ingresos.','https://www.gerty.com/aseguradoras-y-empresas'),
 ('ENT-RUT-77576082-6','B2B2C','AMBOS','SUSCRIPCION_SAAS',0.999::numeric,0.999::numeric,0.99::numeric,'Pawer ofrece planes individuales de salud/seguro veterinario y una solución Pawer Empresas como beneficio para colaboradores.','La oferta vigente atiende personas directamente y empresas que contratan o facilitan planes a sus colaboradores.','Los planes funcionan bajo pago recurrente/suscripción; en empresas el valor depende de colaboradores y coberturas y puede ser pagado por la empresa o directamente por el colaborador.','https://ayuda.somospawer.com/es/articles/7992028-precios-de-planes-pawer-empresas-valores-y-formas-de-pago')
), logged as (
 insert into public.aml_fintech_profile_audit(fintech_id,classifier_version,business_model,business_model_confidence,target_customer,target_customer_confidence,revenue_model,revenue_model_confidence,pages_scanned,observed_at,evidence)
 select v.fintech_id,'MANUAL_OFFICIAL_INSURTECH_COMPLETION_2026_09_09',v.business_model,v.bm_conf,v.target_customer,v.tc_conf,coalesce(v.revenue_model,e.revenue_model),coalesce(v.rev_conf,e.revenue_model_confidence),1,now(),jsonb_build_object('source_url',v.source_url,'business_model_basis',v.bm_basis,'target_customer_basis',v.tc_basis,'revenue_model_basis',v.rev_basis,'manual_validation',true,'cohort','INSURTECH_COMPLETION')
 from vals v join public.aml_fintech_entity e using(fintech_id)
 returning fintech_id
)
update public.aml_fintech_entity e
set business_model=v.business_model,target_customer=v.target_customer,revenue_model=coalesce(v.revenue_model,e.revenue_model),business_model_basis=v.bm_basis,business_model_confidence=v.bm_conf,target_customer_basis=v.tc_basis,target_customer_confidence=v.tc_conf,revenue_model_basis=case when v.revenue_model is not null then v.rev_basis else e.revenue_model_basis end,revenue_model_confidence=case when v.revenue_model is not null then v.rev_conf else e.revenue_model_confidence end,profile_classifier_version='MANUAL_OFFICIAL_INSURTECH_COMPLETION_2026_09_09',profile_refreshed_at=now(),refreshed_at=now()
from vals v where e.fintech_id=v.fintech_id and exists(select 1 from logged l where l.fintech_id=e.fintech_id);

